const patterns = patternData as DsaPattern[];
const questionsById = new Map(foundry75Questions.map((question) => [question.id, question]));

export const dsaPatternLessons: DsaPatternLesson[] = patterns.map((pattern) => ({ ...pattern, ...lessonFields[pattern.slug] }));

if (dsaPatternLessons.length !== 20 || new Set(dsaPatternLessons.map((lesson) => lesson.slug)).size !== 20) {
  throw new Error("The Required DSA pattern catalog must contain exactly 20 unique lessons.");
}
for (const lesson of dsaPatternLessons) {
  if (!lessonFields[lesson.slug] || !lesson.problemShape || !lesson.antiClues.length || !lesson.derivation.length || !lesson.trace.length || !lesson.narration.length || !lesson.followUps.length || !lesson.errorLogPrompts.length || !lesson.relatedPatterns.length) {
    throw new Error(`DSA pattern ${lesson.slug} is missing its full lesson contract.`);
  }
  const worked = questionsById.get(lesson.workedProblemId);
  if (!worked || !worked.patterns.includes(lesson.slug)) {
    throw new Error(`DSA pattern ${lesson.slug} needs a matching Foundry 75 worked problem.`);
  }
}

export const dsaPatternLessonBySlug = new Map(dsaPatternLessons.map((lesson) => [lesson.slug, lesson]));
